fn sumEven(nums: [int]) -> int {
    var total = 0
    for x in nums {
        if x % 2 == 0 { total += x }
    }
    total
}

fn countVowels(s: str) -> int {
    var n = 0
    for c in s {
        if c == 'a' || c == 'e' || c == 'i' || c == 'o' || c == 'u' {
            n += 1
        }
    }
    n
}

fn isPalindrome(s: str) -> bool {
    let n = s.len()
    for i in 0..(n / 2) {
        if s[i] != s[n - 1 - i] { return false }
    }
    true
}

fn reverseWords(s: str) -> str {
    s.split(" ").reverse().join(" ")
}

fn factorial(n: int) -> int {
    var result = 1
    for i in 2..=n {
        result *= i
    }
    result
}

fn isPrime(n: int) -> bool {
    if n < 2 { return false }
    if n < 4 { return true }
    if n % 2 == 0 { return false }
    var i = 3
    while i * i <= n {
        if n % i == 0 { return false }
        i += 2
    }
    true
}

fn fibonacci(n: int) -> int {
    var a = 0
    var b = 1
    for _ in 0..n {
        var t = a + b
        a = b
        b = t
    }
    a
}

fn maxOfList(nums: [int]) -> int {
    nums.max()
}

fn filterPositive(nums: [int]) -> [int] {
    nums.filter(|x| x > 0)
}

fn collatzSteps(n: int) -> int {
    var x = n
    var steps = 0
    while x != 1 {
        if x % 2 == 0 { x /= 2 } else { x = 3 * x + 1 }
        steps += 1
    }
    steps
}

fn runLengthEncode(s: str) -> str {
    var out = ""
    var i = 0
    while i < s.len() {
        var c = s[i]
        var count = 0
        while i < s.len() && s[i] == c {
            count += 1
            i += 1
        }
        out += strFromByte(c) + str(count)
    }
    out
}

fn balancedParens(s: str) -> bool {
    var depth = 0
    for c in s {
        if c == '(' {
            depth += 1
        } else if c == ')' {
            depth -= 1
            if depth < 0 { return false }
        }
    }
    depth == 0
}

fn longestRun(nums: [int]) -> int {
    var best = 0
    var cur = 0
    var prev = 0
    var first = true
    for x in nums {
        if first {
            cur = 1
            prev = x
            first = false
        } else if x == prev {
            cur += 1
        } else {
            cur = 1
            prev = x
        }
        if cur > best { best = cur }
    }
    best
}

fn mergeSorted(a: [int], b: [int]) -> [int] {
    var out: [int] = []
    var i = 0
    var j = 0
    while i < a.len() && j < b.len() {
        if a[i] <= b[j] {
            out.push(a[i])
            i += 1
        } else {
            out.push(b[j])
            j += 1
        }
    }
    while i < a.len() {
        out.push(a[i])
        i += 1
    }
    while j < b.len() {
        out.push(b[j])
        j += 1
    }
    out
}

fn removeDuplicates(nums: [int]) -> [int] {
    var seen: Set<int> = setNew()
    var out: [int] = []
    for x in nums {
        if !seen.has(x) {
            seen.add(x)
            out.push(x)
        }
    }
    out
}

fn caesarShift(s: str, k: int) -> str {
    var out = ""
    for c in s {
        var code = ord(c)
        if code >= ord('a') && code <= ord('z') {
            code = ord('a') + (code - ord('a') + k) % 26
        }
        out += strFromByte(code)
    }
    out
}

fn toBinary(n: int) -> str {
    if n == 0 { return "0" }
    var bits: [str] = []
    var x = n
    while x > 0 {
        bits.push(strFromByte(ord('0') + x % 2))
        x /= 2
    }
    bits.reverse().join("")
}

fn digitSum(n: int) -> int {
    var total = 0
    var x = n
    while x > 0 {
        total += x % 10
        x = x / 10
    }
    total
}

fn twoSum(nums: [int], target: int) -> [int] {
    for i in 0..nums.len() {
        for j in i + 1..nums.len() {
            if nums[i] + nums[j] == target {
                return [i, j]
            }
        }
    }
    [-1, -1]
}

fn maxSubarraySum(nums: [int]) -> int {
    var best = nums[0]
    var cur = nums[0]
    for i in 1..nums.len() {
        cur = max(cur + nums[i], nums[i])
        best = max(best, cur)
    }
    best
}

fn primeFactors(n: int) -> [int] {
    var result: [int] = []
    var m = n
    var d = 2
    while d * d <= m {
        while m % d == 0 {
            result.push(d)
            m /= d
        }
        d += 1
    }
    if m > 1 { result.push(m) }
    result
}

fn wordLengths(s: str) -> [int] {
    var out: [int] = []
    for w in s.words() { out.push(w.len()) }
    out
}

fn capitalizeWords(s: str) -> str {
    var out = ""
    var first = true
    for c in s {
        if c == ' ' {
            out += c
            first = true
        } else {
            if first && c >= 'a' && c <= 'z' {
                out += chr(ord(c) - 32)
            } else {
                out += c
            }
            first = false
        }
    }
    out
}

fn longestCommonPrefix(words: [str]) -> str {
    if words.len() == 0 { return "" }
    var prefix = words[0]
    for w in words {
        var n = min(prefix.len(), w.len())
        var i = 0
        while i < n && prefix[i] == w[i] {
            i += 1
        }
        prefix = prefix[0..i]
    }
    prefix
}

fn rotateLeft(nums: [int], k: int) -> [int] {
    var n = nums.len()
    if n == 0 { return [] }
    var kk = k % n
    var res: [int] = []
    for i in kk..n { res.push(nums[i]) }
    for i in 0..kk { res.push(nums[i]) }
    res
}

fn fizzBuzz(n: int) -> [str] {
    var out: [str] = []
    for i in 1..=n {
        if i % 15 == 0 {
            out.push("FizzBuzz")
        } else if i % 3 == 0 {
            out.push("Fizz")
        } else if i % 5 == 0 {
            out.push("Buzz")
        } else {
            out.push(str(i))
        }
    }
    out
}

fn isAnagram(a: str, b: str) -> bool {
    if a.len() != b.len() { return false }
    var counts: Map<str, int> = mapNew()
    for c in a { counts[c] += 1 }
    for c in b { counts[c] -= 1 }
    for k in counts.keys() {
        if counts[k] != 0 { return false }
    }
    true
}

fn secondLargest(nums: [int]) -> int {
    var seen: Set<int> = setNew()
    var vals: [int] = []
    for x in nums {
        if !seen.has(x) {
            seen.add(x)
            vals.push(x)
        }
    }
    if vals.len() < 2 { return -1 }
    var first = vals.max()
    var second = -1
    var found = false
    for v in vals {
        if v != first {
            if !found || v > second {
                second = v
                found = true
            }
        }
    }
    second
}

fn pascalRow(n: int) -> [int] {
    var row: [int] = [1]
    for i in 0..n {
        var next: [int] = [1]
        for j in 0..row.len() - 1 {
            next.push(row[j] + row[j + 1])
        }
        next.push(1)
        row = next
    }
    row
}

fn greatestCommonDivisor(a: int, b: int) -> int {
    var x = a
    var y = b
    while y > 0 {
        var t = x % y
        x = y
        y = t
    }
    x
}

fn sortAscending(nums: [int]) -> [int] {
    var result: [int] = []
    for x in nums { result.push(x) }
    result.sort()
    result
}

fn mostFrequent(nums: [int]) -> int {
    var m: Map<int, int> = mapNew()
    for x in nums { m[x] += 1 }
    var best = nums[0]
    var bestCount = m[best]
    for x in nums {
        if m[x] > bestCount || (m[x] == bestCount && x < best) {
            best = x
            bestCount = m[x]
        }
    }
    best
}

fn collapseSpaces(s: str) -> str {
    var out = ""
    var prevSpace = true
    for c in s {
        if c == ' ' {
            if !prevSpace { out += " " }
            prevSpace = true
        } else {
            out += c
            prevSpace = false
        }
    }
    if prevSpace && out.len() > 0 {
        out = out[0..out.len() - 1]
    }
    out
}

fn runningMaximum(nums: [int]) -> [int] {
    var out: [int] = []
    var cur = 0
    for x in nums {
        if out.len() == 0 || x > cur { cur = x }
        out.push(cur)
    }
    out
