struct MergeResult {
    inv: int
    merged: [int]
}

fn mergeCount(a: [int], b: [int]) -> MergeResult {
    var inv = 0
    var merged: [int] = []
    var i = 0
    var j = 0
    while i < a.len() && j < b.len() {
        if a[i] <= b[j] {
            merged.push(a[i])
            i += 1
        } else {
            merged.push(b[j])
            j += 1
            inv += a.len() - i
        }
    }
    while i < a.len() { merged.push(a[i]); i += 1 }
    while j < b.len() { merged.push(b[j]); j += 1 }
    MergeResult { inv: inv, merged: merged }
}

fn sortCount(nums: [int]) -> MergeResult {
    if nums.len() <= 1 {
        return MergeResult { inv: 0, merged: nums }
    }
    let mid = nums.len() / 2
    let left = sortCount(nums[0..mid])
    let right = sortCount(nums[mid..nums.len()])
    let m = mergeCount(left.merged, right.merged)
    MergeResult { inv: left.inv + right.inv + m.inv, merged: m.merged }
}

fn countInversions(nums: [int]) -> int {
    sortCount(nums).inv
}

fn toHex(n: int) -> str {
    if n == 0 { return "0" }
    var digits = "0123456789abcdef"
    var x = n
    var out = ""
    while x > 0 {
        out = strFromByte(ord(digits[x % 16])) + out
        x = x / 16
    }
    out
}

