fn wordsStartingWithVowel(words: [str]) -> [str] {
    words.filter(|w| w.len() > 0 && "aeiou".contains(strFromByte(w[0])))
}

fn integerSqrt(n: int) -> int {
    var lo = 0
    var hi = n
    while lo < hi {
        var mid = (lo + hi + 1) / 2
        if mid <= n / mid {
            lo = mid
        } else {
            hi = mid - 1
        }
    }
    lo
}

fn interleave(a: [int], b: [int]) -> [int] {
    var out: [int] = []
    var n = min(a.len(), b.len())
    for i in 0..n {
        out.push(a[i])
        out.push(b[i])
    }
    for x in a[n..a.len()] { out.push(x) }
    for x in b[n..b.len()] { out.push(x) }
    out
}

fn charCodeSum(s: str) -> int {
    var total = 0
    for c in s {
        total += ord(c)
    }
    total
}

fn joinUppercase(words: [str], sep: str) -> str {
    words.map(|w| w.upper()).join(sep)
}

fn bestProfit(prices: [int]) -> int {
    var best = 0
    var lowest = prices[0]
    for i in 1..prices.len() {
        if prices[i] - lowest > best { best = prices[i] - lowest }
        if prices[i] < lowest { lowest = prices[i] }
    }
    best
}

fn missingNumber(nums: [int]) -> int {
    var total = 0
    for x in nums { total += x }
    let n = nums.len()
    n * (n + 1) / 2 - total
}

fn toRoman(n: int) -> str {
    let vals = [1000, 900, 500, 400, 100, 90, 50, 40, 10, 9, 5, 4, 1]
    let syms = ["M", "CM", "D", "CD", "C", "XC", "L", "XL", "X", "IX", "V", "IV", "I"]
    var res = ""
    var x = n
    for i in 0..vals.len() {
        while x >= vals[i] {
            res += syms[i]
            x -= vals[i]
        }
    }
    res
}

fn average(nums: [int]) -> float {
    float(nums.sum()) / float(nums.len())
}

fn celsiusToFahrenheit(c: float) -> float {
    c * 9.0 / 5.0 + 32.0
}

fn countWords(s: str) -> int {
    s.words().len()
}

fn allUnique(nums: [int]) -> bool {
    var seen: Set<int> = setNew()
    for x in nums {
        if seen.has(x) { return false }
        seen.add(x)
    }
    true
}

fn clampValues(nums: [int], lo: int, hi: int) -> [int] {
    nums.map(|x| min(max(x, lo), hi))
}

fn stringRepeat(s: str, n: int) -> str {
    var result = ""
    for i in 0..n {
        result += s
    }
    result
}

fn powerMod(base: int, exp: int, m: int) -> int {
    var b = base % m
    var result = 1 % m
    var e = exp
    while e > 0 {
        if e % 2 == 1 {
            result = (result * b) % m
        }
        b = (b * b) % m
        e = e / 2
    }
    result
}

fn lastIndexOf(nums: [int], target: int) -> int {
    var result = -1
    for i in 0..nums.len() {
        if nums[i] == target { result = i }
    }
    result
}

fn stripDigits(s: str) -> str {
    var out = ""
    for c in s {
        if !(ord(c) >= ord('0') && ord(c) <= ord('9')) {
            out += c
        }
    }
    out
}

fn pairwiseDifferences(nums: [int]) -> [int] {
    var diffs: [int] = []
    for i in 0..nums.len() - 1 {
        diffs.push(nums[i + 1] - nums[i])
    }
    diffs
}

fn leapYear(year: int) -> bool {
    (year % 4 == 0 && year % 100 != 0) || year % 400 == 0
}

fn longestWord(words: [str]) -> str {
    var best = words[0]
    for w in words {
        if w.len() > best.len() { best = w }
    }
    best
}

fn countChar(s: str, ch: str) -> int {
    var n = 0
    for c in s {
        if c == ch { n += 1 }
    }
    n
}

fn triangleKind(a: int, b: int, c: int) -> str {
    if a + b <= c || a + c <= b || b + c <= a {
        return "invalid"
    }
    if a == b && b == c {
        "equilateral"
    } else if a == b || b == c || a == c {
        "isosceles"
    } else {
        "scalene"
    }
}

fn dotProduct(a: [int], b: [int]) -> int {
    var total = 0
    for i in 0..a.len() {
        total += a[i] * b[i]
    }
    total
}

fn swapCase(s: str) -> str {
    var out = ""
    for c in s {
        var code = ord(c)
        if code >= 'a' && code <= 'z' {
            out += strFromByte(code - 32)
        } else if code >= 'A' && code <= 'Z' {
            out += strFromByte(code + 32)
        } else {
            out += c
        }
    }
    out
}
